import Foundation
import SQLite3
// SQL failures are infrastructure failures; business rejections remain typed.
struct JsonRow:Sendable{let position:Int;let commandId:String;let eventType:String;let payloadJson:String;let tagsJson:String}
protocol JsonJournal:AnyObject,Sendable{var version:String{get};func read(_ q:Query,_ after:Int)->(Int,[JsonRow]);func append(_ id:String,_ q:Query,_ after:Int,_ events:[JsonRow])->[JsonRow]?;func load(_ events:[JsonRow]);func close()}
func tagKeys(_ keys:[String])->Data{var data=Data();for key in keys{let bytes=Data(key.utf8);var n=UInt32(bytes.count).bigEndian;withUnsafeBytes(of:&n){data.append(contentsOf:$0)};data.append(bytes)};return data}
private func tagKey(_ t:DcbTag)->Data{tagKeys([t.category]+t.keys)}
private func decodeTags(_ json:String)->[DcbTag]{let ts=try! JSONDecoder().decode([DcbTag].self,from:Data(json.utf8));precondition(Set(ts.map(tagKey)).count == ts.count,"duplicate tag");return ts}
final class MemoryJsonJournal:JsonJournal,@unchecked Sendable{
 private let gate=NSLock();private var log:[JsonRow]=[];private var tags:[Data:[Int]]=[:];private var types:[Data:[Int]]=[:];let version="memory-json-v1"
 private func positions(_ q:Query,_ after:Int)->[Int]{precondition(after>=0 && after<=log.count);var all=Set<Int>();let items=q.items.isEmpty ? [QueryItem(tags:[],types:[])]:q.items;for item in items{var sets=item.tags.map{tags[tagKey($0)] ?? []};if !item.types.isEmpty{sets.append(item.types.flatMap{types[Data($0.utf8)] ?? []})};if sets.isEmpty{if after<log.count{all.formUnion((after+1)...log.count)};continue};var selected=Set(sets[0]);for ps in sets.dropFirst(){selected.formIntersection(ps)};all.formUnion(selected.filter{$0>after})};return all.sorted()}
 func read(_ q:Query,_ after:Int)->(Int,[JsonRow]){gate.lock();defer{gate.unlock()};return(log.count,positions(q,after).map{log[$0-1]})}
 func append(_ id:String,_ q:Query,_ after:Int,_ events:[JsonRow])->[JsonRow]?{gate.lock();defer{gate.unlock()};precondition(!id.isEmpty && !events.isEmpty);if !positions(q,after).isEmpty{return nil};let pending=events.enumerated().map{i,e in _=decodeTags(e.tagsJson);return JsonRow(position:log.count+i+1,commandId:id,eventType:e.eventType,payloadJson:e.payloadJson,tagsJson:e.tagsJson)};for e in pending{log.append(e);types[Data(e.eventType.utf8),default:[]].append(e.position);for t in decodeTags(e.tagsJson){tags[tagKey(t),default:[]].append(e.position)}};return pending}
 func load(_ events:[JsonRow]){gate.lock();defer{gate.unlock()};precondition(log.isEmpty);for(i,e)in events.enumerated(){precondition(e.position==i+1);_=decodeTags(e.tagsJson)};for e in events{log.append(e);types[Data(e.eventType.utf8),default:[]].append(e.position);for t in decodeTags(e.tagsJson){tags[tagKey(t),default:[]].append(e.position)}}}
 func close(){}
}
final class SqliteJournal:JsonJournal,@unchecked Sendable{
 private let gate=NSLock();private var db:OpaquePointer?;private var statements:[String:OpaquePointer]=[:];private(set)var version=""
 private enum Value{case text(String),int(Int),blob(Data)}
 private let transient=unsafeBitCast(-1,to:sqlite3_destructor_type.self)
 init(_ path:String,_ durability:String="FULL"){
  precondition(["FULL","NORMAL"].contains(durability));try! FileManager.default.createDirectory(at:URL(fileURLWithPath:path).deletingLastPathComponent(),withIntermediateDirectories:true)
  precondition(sqlite3_open(path,&db)==SQLITE_OK,"open SQLite failed")
  for q in ["PRAGMA journal_mode=WAL","PRAGMA synchronous=\(durability)","PRAGMA foreign_keys=ON","PRAGMA busy_timeout=5000","PRAGMA cache_size=-2048","PRAGMA wal_autocheckpoint=1000","CREATE TABLE IF NOT EXISTS events(position INTEGER PRIMARY KEY,command_id TEXT NOT NULL,event_type TEXT NOT NULL,payload_json TEXT NOT NULL,tags_json TEXT NOT NULL)","CREATE TABLE IF NOT EXISTS event_tags(position INTEGER NOT NULL REFERENCES events(position),category TEXT NOT NULL,keys_key BLOB NOT NULL,PRIMARY KEY(position,category,keys_key))","CREATE INDEX IF NOT EXISTS tags_match ON event_tags(category,keys_key,position)","CREATE INDEX IF NOT EXISTS events_type_position ON events(event_type,position)"]{exec(q)}
  let v=stmt("PRAGMA user_version",[]);precondition(sqlite3_step(v)==SQLITE_ROW);precondition([0,1].contains(Int(sqlite3_column_int(v,0))),"unsupported schema version");sqlite3_reset(v);exec("PRAGMA user_version=1")
  let s=stmt("SELECT sqlite_version()",[]);precondition(sqlite3_step(s)==SQLITE_ROW);version=String(cString:sqlite3_column_text(s,0));sqlite3_reset(s)
 }
 private func check(_ rc:Int32){precondition(rc==SQLITE_OK,String(cString:sqlite3_errmsg(db)))}
 private func stmt(_ sql:String,_ args:[Value])->OpaquePointer{let s:OpaquePointer;if let p=statements[sql]{s=p}else{var p:OpaquePointer?;check(sqlite3_prepare_v2(db,sql,-1,&p,nil));s=p!;statements[sql]=s};check(sqlite3_reset(s));check(sqlite3_clear_bindings(s));for(i,v)in args.enumerated(){let n=Int32(i+1);switch v{case .int(let x):check(sqlite3_bind_int64(s,n,Int64(x)));case .text(let x):check(sqlite3_bind_text(s,n,x,Int32(x.utf8.count),transient));case .blob(let b):if b.isEmpty{check(sqlite3_bind_zeroblob(s,n,0))}else{b.withUnsafeBytes{check(sqlite3_bind_blob(s,n,$0.baseAddress,Int32(b.count),transient))}}}};return s}
 private func exec(_ sql:String,_ args:[Value]=[]){let s=stmt(sql,args);var rc=sqlite3_step(s);while rc==SQLITE_ROW{rc=sqlite3_step(s)};precondition(rc==SQLITE_DONE,String(cString:sqlite3_errmsg(db)));check(sqlite3_reset(s))}
 private func high()->Int{let s=stmt("SELECT COALESCE(MAX(position),0) FROM events",[]);precondition(sqlite3_step(s)==SQLITE_ROW);let n=Int(sqlite3_column_int64(s,0));sqlite3_reset(s);return n}
 private func selection(_ q:Query,_ low:Int,_ high:Int,_ exists:Bool)->(String,[Value]){var args:[Value]=[];func param(_ v:Value)->String{args.append(v);return "?"};func range()->String{"position>"+param(.int(low))+" AND position<="+param(.int(high))};let condition:String;if q.items.isEmpty || q.items.contains(where:{$0.tags.isEmpty && $0.types.isEmpty}){condition=range()}else{let alts=q.items.map{item in var terms=item.tags.map{t in "SELECT position FROM event_tags WHERE category="+param(.text(t.category))+" AND keys_key="+param(.blob(tagKeys(t.keys)))+" AND "+range()};if !item.types.isEmpty{terms.append("SELECT position FROM events WHERE event_type IN ("+item.types.map{param(.text($0))}.joined(separator:",")+") AND "+range())};return "SELECT position FROM ("+terms.joined(separator:" INTERSECT ")+")"};condition="position IN ("+alts.joined(separator:" UNION ")+")"};return("SELECT "+(exists ? "1":"position,command_id,event_type,payload_json,tags_json")+" FROM events WHERE "+condition+(exists ? " LIMIT 1":" ORDER BY position"),args)}
 func read(_ q:Query,_ after:Int)->(Int,[JsonRow]){gate.lock();defer{gate.unlock()};exec("BEGIN");let n=high();precondition(after>=0 && after<=n);let(sql,args)=selection(q,after,n,false),s=stmt(sql,args);var out:[JsonRow]=[];var rc=sqlite3_step(s);while rc==SQLITE_ROW{func text(_ i:Int32)->String{String(cString:sqlite3_column_text(s,i))};out.append(JsonRow(position:Int(sqlite3_column_int64(s,0)),commandId:text(1),eventType:text(2),payloadJson:text(3),tagsJson:text(4)));rc=sqlite3_step(s)};precondition(rc==SQLITE_DONE);sqlite3_reset(s);exec("COMMIT");return(n,out)}
 func append(_ id:String,_ q:Query,_ after:Int,_ events:[JsonRow])->[JsonRow]?{gate.lock();defer{gate.unlock()};exec("BEGIN IMMEDIATE");let n=high();precondition(!id.isEmpty && !events.isEmpty && after>=0 && after<=n);let(sql,args)=selection(q,after,n,true),s=stmt(sql,args);let rc=sqlite3_step(s);sqlite3_reset(s);if rc==SQLITE_ROW{exec("ROLLBACK");return nil};precondition(rc==SQLITE_DONE);var rows:[JsonRow]=[];for e in events{let row=JsonRow(position:n+rows.count+1,commandId:id,eventType:e.eventType,payloadJson:e.payloadJson,tagsJson:e.tagsJson);exec("INSERT INTO events VALUES(?,?,?,?,?)",[.int(row.position),.text(id),.text(row.eventType),.text(row.payloadJson),.text(row.tagsJson)]);for t in decodeTags(row.tagsJson){exec("INSERT INTO event_tags VALUES(?,?,?)",[.int(row.position),.text(t.category),.blob(tagKeys(t.keys))])};rows.append(row)};exec("COMMIT");return rows}
 func load(_ events:[JsonRow]){gate.lock();defer{gate.unlock()};exec("BEGIN IMMEDIATE");precondition(high()==0);for(i,e)in events.enumerated(){precondition(e.position==i+1);exec("INSERT INTO events VALUES(?,?,?,?,?)",[.int(e.position),.text(e.commandId),.text(e.eventType),.text(e.payloadJson),.text(e.tagsJson)]);for t in decodeTags(e.tagsJson){exec("INSERT INTO event_tags VALUES(?,?,?)",[.int(e.position),.text(t.category),.blob(tagKeys(t.keys))])}};exec("COMMIT")}
 func close(){gate.lock();defer{gate.unlock()};for s in statements.values{check(sqlite3_finalize(s))};statements.removeAll();check(sqlite3_close(db));db=nil}
}
final class JsonEventStore<E:Sendable>:CommandStore,@unchecked Sendable{
 typealias Payload=E
 private let gate=NSRecursiveLock();private let journal:any JsonJournal;private let describe:@Sendable(E)->EventDescriptor;private let encode:@Sendable(E)->String;private let decode:@Sendable(String)->E;private var listeners:[@Sendable([Recorded<E>])->Bool]=[];private var published=0;private(set)var listenerFaults=0;private(set)var encoded=0;private(set)var decoded=0;private(set)var encodedBytes=0;private(set)var decodedBytes=0
 var version:String{journal.version}
 init(_ journal:any JsonJournal,_ describe:@escaping @Sendable(E)->EventDescriptor,_ encode:@escaping @Sendable(E)->String,_ decode:@escaping @Sendable(String)->E){self.journal=journal;self.describe=describe;self.encode=encode;self.decode=decode}
 private func encodeEvent(_ id:String,_ e:E)->JsonRow{let m=describe(e),json=encode(e);precondition(!m.eventType.isEmpty);encoded+=1;encodedBytes+=json.utf8.count;return JsonRow(position:0,commandId:id,eventType:m.eventType,payloadJson:json,tagsJson:String(data:try! JSONEncoder().encode(m.tags),encoding:.utf8)!)}
 private func decodeRows(_ rows:[JsonRow])->[Recorded<E>]{rows.map{e in let p=decode(e.payloadJson),ts=decodeTags(e.tagsJson),m=describe(p);precondition(m.eventType.utf8.elementsEqual(e.eventType.utf8) && m.tags.count==ts.count && m.tags.allSatisfy{ts.contains($0)},"invalid stored metadata");decoded+=1;decodedBytes+=e.payloadJson.utf8.count;return Recorded(position:e.position,commandId:e.commandId,eventType:e.eventType,tags:ts,payload:p)}}
 func read(_ q:Query)->ReadResult<E>{gate.lock();defer{gate.unlock()};let(n,rows)=journal.read(q,0);return ReadResult(after:n,events:decodeRows(rows))}
 func refresh(){gate.lock();defer{gate.unlock()};if listeners.isEmpty{return};let(n,rows)=journal.read(Query(items:[]),published),events=decodeRows(rows);listeners=listeners.filter{l in let ok=l(events);if !ok{listenerFaults+=1};return ok};published=n}
 func append(_ id:String,_ q:Query,_ after:Int,_ batch:[E])->AppendResult<E>{gate.lock();defer{gate.unlock()};guard let rows=journal.append(id,q,after,batch.map{encodeEvent(id,$0)})else{return .conflict};if listeners.isEmpty{published=rows.last!.position}else{refresh()};return .committed(decodeRows(rows))}
 func subscribe(_ l:@escaping @Sendable([Recorded<E>])->Bool){gate.lock();defer{gate.unlock()};if !listeners.isEmpty{refresh()};let(n,rows)=journal.read(Query(items:[]),0);precondition(l(decodeRows(rows)),"replay failed");listeners.append(l);published=n}
 func load(_ events:[Recorded<E>]){gate.lock();defer{gate.unlock()};precondition(listeners.isEmpty);let rows=events.enumerated().map{i,e in let row=encodeEvent(e.commandId,e.payload),ts=decodeTags(row.tagsJson);precondition(e.position==i+1 && !e.commandId.isEmpty && row.eventType==e.eventType && ts.count==e.tags.count && ts.allSatisfy{e.tags.contains($0)},"invalid imported metadata");return JsonRow(position:e.position,commandId:e.commandId,eventType:row.eventType,payloadJson:row.payloadJson,tagsJson:row.tagsJson)};journal.load(rows)}
 func close(){journal.close()}
}
